\title{The Sharp Order-Driven Lower Bound for Adjacent-Vertex-Distinguishing
Total Colourings of Central Graphs}
\author{Aristotle}
\date{2026-07-14}

\begin{document}

\begin{abstract}
The \emph{central graph} $\CG$ of a finite simple graph $G$ is obtained by
subdividing every edge of $G$ once and joining every pair of non-adjacent
vertices of $G$. Its structure has a distinctive feature: while each subdivision
vertex has degree $2$, every original vertex has degree $|V(G)|-1$, so all
original vertices are maximum-degree vertices whose common degree depends only on
the \emph{order} of $G$. We study the \emph{adjacent-vertex-distinguishing (AVD)
total chromatic number} $\chi''_a(\CG)$. A previously known bound for
$d$-regular non-complete graphs asserts $\chi''_a(\CG)\ge d+3$. We prove the
strictly stronger, order-driven bound $\chi''_a(\CG)\ge |V(G)|+1$ for every
non-complete $G$, and show it dominates the degree bound: any $d$-regular
non-complete graph satisfies $|V(G)|\ge d+2$, hence $|V(G)|+1\ge d+3$, strictly
whenever $|V(G)|>d+2$. The five-cycle $C_5$ realises the smallest strict
separation, requiring $6$ colours where the degree bound predicts $5$. The
central mechanism is an \emph{adjacent equal-degree obstruction}: at a
maximum-degree vertex a palette of size $\deg+1$ is forced to use every colour,
so two adjacent equal-degree vertices acquire identical colour sets. Because
non-adjacent pairs of $G$ become adjacent equal-degree pairs in $\CG$, the
obstruction fires precisely when $G$ is not complete, isolating complete graphs
as the unique exceptional family.
\end{abstract}

\maketitle

\section{Introduction}

Colouring problems typically measure difficulty through \emph{degree}. This paper
concerns a construction --- the central graph --- for which degree-based
intuition gives a valid but suboptimal answer, and where the true controlling
invariant is the \emph{order} of the underlying graph.

Let $G$ be a finite simple graph with vertex set $V(G)$ and edge set $E(G)$. Its
central graph $\CG$ subdivides each edge once and adds an edge between each pair
of non-adjacent vertices. This double action produces a graph on $V(G)\sqcup
E(G)$ in which all original vertices attain the common degree $|V(G)|-1$. We study
\emph{total colourings} of $\CG$ that are proper and additionally
\emph{distinguish adjacent vertices by their colour sets}.

The literature records, for $d$-regular non-complete graphs, the bound
$\chi''_a(\CG)\ge d+3$. Our contribution is to show this measures the wrong
quantity: the correct first-order invariant is $|V(G)|$, and
$\chi''_a(\CG)\ge |V(G)|+1$ for every non-complete $G$, a bound recovering and
strictly improving the degree bound. The argument is structural and rests on a
single obstruction concerning adjacent vertices of equal degree.

\section{Preliminaries: total graphs, colour sets, and the AVD condition}

Let $H$ be a finite simple graph on vertex set $W$.

\begin{definition}[Total graph]
The \emph{total graph} $T(H)$ has vertex set $V(T(H))=W\sqcup E(H)$. Two vertices
of $T(H)$ are adjacent exactly when: (1) they are original vertices $a,b\in W$
adjacent in $H$; (2) one is a vertex $a$ and the other an edge $e$ with $a\in e$;
or (3) they are distinct edges $e\ne f$ sharing an endpoint. The relation is
symmetric and irreflexive, so $T(H)$ is a simple graph.
\end{definition}

\begin{definition}[Total colouring]
A \emph{total colouring} of $H$ with palette $\kappa$ is a proper colouring
$C:V(T(H))\to\kappa$ of $T(H)$.
\end{definition}

\begin{definition}[Star at a vertex]
For $w\in W$, the \emph{star} at $w$ consists of $w$ together with all edges of
$H$ incident to $w$, viewed as vertices of $T(H)$.
\end{definition}

\begin{lemma}[Star clique]\label{lem:starclique}
The star at $w$ is a clique of $T(H)$.
\end{lemma}

\begin{proof}
$w$ is adjacent to each incident edge by incidence; any two distinct edges
incident to $w$ share the endpoint $w$, hence are adjacent.
\end{proof}

\begin{lemma}[Star size]\label{lem:starsize}
The star at $w$ has exactly $\deg_H(w)+1$ members. Consequently any palette needs
at least $\deg_H(w)+1$ colours, and the map $i\mapsto C(\text{star member } i)$ is
injective.
\end{lemma}

\begin{definition}[Colour set]
Given a total colouring $C$, the \emph{colour set} of $w$ is
\[
\Cset(w)=\{C(w)\}\cup\{C(e):e\in E(H),\ w\in e\}.
\]
\end{definition}

\begin{definition}[AVD total colouring]
A total colouring $C$ is \emph{adjacent-vertex-distinguishing (AVD)} if
$\Cset(a)\ne\Cset(b)$ for every pair of adjacent vertices $a\ne b$. The
\emph{AVD-total chromatic number} $\chi''_a(H)$ is the least palette size
admitting an AVD total colouring ($+\infty$ if none exists).
\end{definition}

\section{The central graph and its degree structure}

\begin{definition}[Central graph]\label{def:central}
The \emph{central graph} $\CG$ of $G$ on vertex set $V$ has vertex set
$V\sqcup E(G)$ and adjacency: (1) original vertices $u\ne w$ are adjacent iff
non-adjacent in $G$; (2) an original vertex $u$ and a subdivision vertex $e$ are
adjacent iff $u\in e$; (3) two subdivision vertices are never adjacent.
\end{definition}

\begin{proposition}[Degrees in $\CG$]\label{prop:deg}
Every subdivision vertex has degree $2$. Every original vertex $v$ has degree
$|V|-1$; equivalently $\deg_{\CG}(v)+1=|V|$.
\end{proposition}

\begin{proof}
A subdivision vertex is adjacent only to its two endpoints. For an original
vertex $v$, its neighbours split into the $(|V|-1)-\deg_G(v)$ original vertices
non-adjacent to $v$ in $G$, and the $\deg_G(v)$ subdivision vertices incident to
$v$. The sum telescopes to $|V|-1$.
\end{proof}

\begin{corollary}[Non-adjacency becomes adjacent equal degree]\label{cor:pair}
If $a,b\in V$ are distinct and non-adjacent in $G$, then $a,b$ are adjacent in
$\CG$ with $\deg_{\CG}(a)=\deg_{\CG}(b)=|V|-1$.
\end{corollary}

\section{The core obstruction and monotonicity}

\begin{lemma}[Palette saturation]\label{lem:sat}
If $C$ uses exactly $\deg_H(w)+1$ colours, then $\Cset(w)=\kappa$.
\end{lemma}

\begin{proof}
By Lemma~\ref{lem:starsize} the star has $\deg_H(w)+1$ members and, being a
clique (Lemma~\ref{lem:starclique}), receives $\deg_H(w)+1$ distinct colours ---
precisely $\Cset(w)$. This set of size $\deg_H(w)+1$ lies in a palette of the same
size, so it is the whole palette.
\end{proof}

\begin{lemma}[Adjacent equal-degree obstruction]\label{lem:obstruction}
If $u,v$ are adjacent in $H$ with $\deg_H(u)=\deg_H(v)=\Delta$ and $C$ uses
exactly $\Delta+1$ colours, then $C$ is not AVD.
\end{lemma}

\begin{proof}
By Lemma~\ref{lem:sat}, $\Cset(u)=\kappa=\Cset(v)$; since $u,v$ are adjacent the
AVD condition fails.
\end{proof}

\begin{lemma}[Padding]\label{lem:pad}
If $H$ admits an AVD total colouring with $n$ colours and $n\le m$, then it admits
one with $m$ colours. Equivalently, the set of admissible palette sizes is upward
closed.
\end{lemma}

\begin{proof}
Fix an injection $\iota:[n]\hookrightarrow[m]$ and set $C'=\iota\circ C$. As
$\iota$ is injective, $C'$ is proper; and $\Cset'(w)=\iota(\Cset(w))$ since colour
sets are images of the star colours and $\iota$ commutes with images. Injectivity
of $\iota$ preserves distinctness, so $C'$ is AVD.
\end{proof}

\section{The sharp order-driven lower bound}

\begin{theorem}[No AVD colouring with $|V|$ colours]\label{thm:eq}
Let $G$ be non-complete, with distinct non-adjacent $a,b\in V$. Then $\CG$ admits
no AVD total colouring using exactly $|V|$ colours.
\end{theorem}

\begin{proof}
By Corollary~\ref{cor:pair}, $a,b$ are adjacent in $\CG$ with common degree
$|V|-1$. A palette of $|V|=(|V|-1)+1$ colours meets Lemma~\ref{lem:obstruction}
with $\Delta=|V|-1$; hence no such colouring is AVD.
\end{proof}

\begin{theorem}[No AVD colouring with $n\le|V|$ colours]\label{thm:le}
Under the same hypotheses, $\CG$ admits no AVD total colouring with any $n\le|V|$.
\end{theorem}

\begin{proof}
Such a colouring would extend, by Lemma~\ref{lem:pad}, to one with exactly $|V|$
colours, contradicting Theorem~\ref{thm:eq}.
\end{proof}

\begin{theorem}[Sharp lower bound]\label{thm:main}
For every non-complete finite simple graph $G$,
\[
\chi''_a(\CG)\ \ge\ |V(G)|+1.
\]
\end{theorem}

\begin{proof}
An AVD total colouring with $n$ colours has $n\ge|V|+1$ by
Theorem~\ref{thm:le}. Taking the infimum gives the bound.
\end{proof}

\section{Domination of the degree bound and the five-cycle}

\begin{lemma}[Order of a regular non-complete graph]\label{lem:order}
If $G$ is $d$-regular and not complete, then $|V(G)|\ge d+2$.
\end{lemma}

\begin{proof}
For a non-adjacent pair $a,b$, the set $\{a\}\cup\{b\}\cup N(a)$ has $d+2$
elements: $a\notin N(a)$, $b\notin N(a)$, $a\ne b$, and $|N(a)|=d$. It lies in
$V(G)$.
\end{proof}

\begin{theorem}[Domination]\label{thm:dom}
For a $d$-regular non-complete graph $G$,
\[
d+3\ \le\ |V(G)|+1\ \le\ \chi''_a(\CG),
\]
with equality on the left iff $|V(G)|=d+2$. The degree bound
$\chi''_a(\CG)\ge d+3$ follows as a corollary, and the order bound is strictly
stronger whenever $|V(G)|>d+2$.
\end{theorem}

\begin{proof}
Add $1$ to Lemma~\ref{lem:order} and chain with Theorem~\ref{thm:main}.
\end{proof}

\begin{proposition}[Five-cycle]\label{prop:c5}
$C_5$ is $2$-regular, non-complete, and $|V(C_5)|=5$; hence
$\chi''_a(C(C_5))\ge 6$, strictly exceeding the degree bound $d+3=5$.
\end{proposition}

\begin{proof}
Each vertex of $C_5$ has degree $2$; the pair $\{0,2\}$ is non-adjacent, so
Theorem~\ref{thm:main} applies with $|V|=5$, giving $6>5=2+3$.
\end{proof}

\section{The exceptional complete case, and open problems}

Every step of the lower bound is triggered by a non-adjacent pair of $G$. When
$G=K_n$ no such pair exists: rule (1) of Definition~\ref{def:central} produces no
edges among original vertices, which form an independent set, and the obstruction
never fires. Thus completeness is the precise and only situation in which the
mechanism is switched off.

\begin{conjecture}[Exact value]
For every non-complete $G$, $\chi''_a(\CG)=|V(G)|+1$.
\end{conjecture}

\begin{conjecture}[Unique exceptional family]
$\chi''_a(\CG)=|V(G)|+1$ holds iff $G$ is non-complete; for complete $G$ the value
is strictly smaller and separately determined.
\end{conjecture}

\begin{conjecture}[Degree-free total chromatic number]
$\chi''(\CG)=|V(G)|$ exactly for non-complete $G$, matching the star-clique lower
bound of size $|V(G)|$ at every original vertex.
\end{conjecture}

\begin{conjecture}[Iterated central graphs]
$\chi''_a(C^k(G))$ grows like the vertex count of $C^{k-1}(G)$ plus one, giving an
explicit recurrence in $k$.
\end{conjecture}

\section{Conclusion}

For central graphs, degree is a red herring. The construction levels every
original vertex to the maximum degree $|V|-1$ and converts non-adjacency into
adjacency, so the decisive obstruction is an adjacent equal-degree pair whose
common degree is dictated by the order of $G$. The sharp bound
$\chi''_a(\CG)\ge|V(G)|+1$ subsumes the degree bound $d+3$, improves it strictly
except in a degenerate case, and singles out complete graphs as the unique
exception. The five-cycle already needs six colours where degree alone predicts
five. The order of the graph, funnelled through its non-adjacent pairs, is the
true first-order invariant.

