function BUILD_CENTRAL_GRAPH(n, E):
  verts <- {('v', i) : 0 <= i < n} U {('e', e) : e in E}
  cedges <- {}
  for each unordered pair {a, b} in verts:
    if a,b both original: adj <- ({a,b} not in E)
    elif one original v, one subdivision e: adj <- (v in e)
    else: adj <- false            # two subdivisions
    if adj: add {a,b} to cedges
  return (verts, cedges)

function BUILD_TOTAL_GRAPH(vertices, edges):
  T <- {('V', v)} U {('E', e)}
  for each unordered pair {x, y} in T:
    if x=('V',a), y=('V',b): link <- ({a,b} in edges)
    if x=('V',a), y=('E',e): link <- (a in e)
    if x=('E',e), y=('E',f): link <- (e and f share endpoint)
    if link: connect x and y
  return adjacency(T)

