from __future__ import annotations
from itertools import combinations
from typing import Dict, FrozenSet, List, Set

def build_total_graph(vertices: List, edges: Set[FrozenSet]
                      ) -> Dict[object, Set[object]]:
    """Construct the total graph T(H) of a graph H = (vertices, edges).

    Total-graph vertices: ("V", v) for each vertex v, ("E", e) for each edge e.
    Adjacency: ("V",a)-("V",b) if a,b adjacent; ("V",a)-("E",e) if a in e;
    ("E",e)-("E",f) if e,f share an endpoint.
    """
    tverts = [("V", v) for v in vertices] + [("E", e) for e in edges]
    adj: Dict[object, Set[object]] = {t: set() for t in tverts}
    edge_of = {("E", e): set(e) for e in edges}
    for x, y in combinations(tverts, 2):
        linked = False
        if x[0] == "V" and y[0] == "V":
            linked = frozenset((x[1], y[1])) in edges
        elif x[0] == "V" and y[0] == "E":
            linked = x[1] in edge_of[y]
        elif x[0] == "E" and y[0] == "V":
            linked = y[1] in edge_of[x]
        else:
            linked = len(edge_of[x] & edge_of[y]) > 0
        if linked:
            adj[x].add(y)
            adj[y].add(x)
    return adj

